def occurence_cord(y,x): #2eme methode taille inconnu
    f1=open("bateaux.dat","rb")
    eof=False
    occ=0
    while not eof :
        try:
            e=load(f1)
            if e["x"]==x and e["y"]==y:
                occ+=1
        except:
            eof=True
    f1.close()
    return occ
